const scenes = $input.all();

return scenes.map((item, index) => {
  const scene = item.json;

  return {
    json: {
      scene_no: scene.scene_number ?? index + 1,
      narration: scene.narration,
      visual_description: scene.visual_description,
      visual_search_keywords: scene.visual_search_keywords,
      approximate_duration_seconds: scene.approximate_duration_seconds
    }
  };
});

const story = $('Message a model').first().json.content;

return [
  {
    json: {
      story
    }
  }
];

const content = $input.first().json.content;

// Extract the JSON array from the AI response
const match = content.match(/\[[\s\S]*\]/);

if (!match) {
  throw new Error("Could not find a JSON scene array in the Ollama response.");
}

let scenes;

try {
  scenes = JSON.parse(match[0]);
} catch (error) {
  throw new Error("Scene Agent returned invalid JSON: " + error.message);
}

// Return each scene as a separate n8n item
return scenes.map(scene => ({
  json: {
    scene_number: scene.scene_number,
    narration: scene.narration,
    visual_description: scene.visual_description,
    visual_search_keywords: scene.visual_search_keywords,
    approximate_duration_seconds: scene.approximate_duration_seconds
  }
}));

const items = $input.all();

return items.map(item => {
  const content = item.json.content;

  const match = content.match(/"search_query"\s*:\s*"([^"]+)"/);

  if (!match) {
    throw new Error("Could not find search_query in Visual Agent output.");
  }

  return {
    json: {
      scene_number: item.json.scene_number,
      search_query: match[1]
    }
  };
});
